     9→import Combine
    10→import Foundation
    11→import UIKit
    12→import UserNotifications
    13→
    14→final class NotificationManager: NSObject, NotificationManagerProtocol {
    15→    private let notificationCenter: UserNotificationCenterProtocol
    16→    private let appSettings: AppSettings
    17→    
    18→    private var userSession: UserSessionProtocol?
    19→    
    20→    private var cancellables = Set<AnyCancellable>()
    21→    private var notificationsEnabled = false
    22→    
    23→    init(notificationCenter: UserNotificationCenterProtocol,
    24→         appSettings: AppSettings) {
    25→        self.notificationCenter = notificationCenter
    26→        self.appSettings = appSettings
    27→        super.init()
    28→    }
    29→
    30→    // MARK: NotificationManagerProtocol
    31→
    32→    weak var delegate: NotificationManagerDelegate?
    33→    
    34→    func start() {
    35→        let replyAction = UNTextInputNotificationAction(identifier: NotificationConstants.Action.inlineReply,
    36→                                                        title: L10n.actionQuickReply,
    37→                                                        options: [])
    38→        let messageCategory = UNNotificationCategory(identifier: NotificationConstants.Category.message,
    39→                                                     actions: [replyAction],
    40→                                                     intentIdentifiers: [],
    41→                                                     options: [])
    42→        
    43→        let inviteCategory = UNNotificationCategory(identifier: NotificationConstants.Category.invite,
    44→                                                    actions: [],
    45→                                                    intentIdentifiers: [],
    46→                                                    options: [])
    47→        notificationCenter.setNotificationCategories([messageCategory, inviteCategory])
    48→        notificationCenter.delegate = self
    49→        
    50→        notificationsEnabled = appSettings.enableNotifications
    51→        MXLog.info("App setting 'enableNotifications' is '\(notificationsEnabled)'")
    52→        
    53→        // Listen for changes to AppSettings.enableNotifications
    54→        appSettings.$enableNotifications
    55→            .sink { [weak self] newValue in
    56→                self?.enableNotifications(newValue)
    57→            }
    58→            .store(in: &cancellables)
    59→    }
    60→        
    61→    func requestAuthorization() {
    62→        guard appSettings.enableNotifications, !userSession.isNil else { return }
    63→        Task {
    64→            do {
    65→                let permissionGranted = try await notificationCenter.requestAuthorization(options: [.alert, .sound, .badge])
    66→                MXLog.info("Permission granted: \(permissionGranted)")
    67→                await MainActor.run {
    68→                    if permissionGranted {
    69→                        self.delegate?.registerForRemoteNotifications()
    70→                    }
    71→                }
    72→            } catch {
    73→                MXLog.error("Request authorization failed: \(error)")
    74→            }
    75→        }
    76→    }
    77→
    78→    func register(with deviceToken: Data) async -> Bool {
    79→        guard let userSession else {
    80→            return false
    81→        }
    82→        return await setPusher(with: deviceToken, clientProxy: userSession.clientProxy)
    83→    }
    84→
    85→    func setUserSession(_ userSession: UserSessionProtocol?) {
    86→        self.userSession = userSession
    87→        
    88→        // If notification permissions were given previously then attempt re-registering
    89→        // for remote notifications on startup. Otherwise let the onboarding flow handle it
    90→        Task { [weak self] in
    91→            guard let self else { return }
    92→            
    93→            if await notificationCenter.authorizationStatus() == .authorized, appSettings.enableNotifications {
    94→                await MainActor.run { [weak self] in
    95→                    self?.delegate?.registerForRemoteNotifications()
    96→                }
    97→            }
    98→            
    99→            let settings = await notificationCenter.notificationSettings()
   100→            MXLog.info("Notification sound enabled: \(settings.soundSetting == .enabled)")
   101→        }
   102→    }
   103→
   104→    func registrationFailed(with error: Error) {
   105→        MXLog.error("Device token registration failed with error: \(error)")
   106→    }
   107→
   108→    func showLocalNotification(with title: String, subtitle: String?) async {
   109→        let content = UNMutableNotificationContent()
   110→        content.title = title
   111→        if let subtitle {
   112→            content.subtitle = subtitle
   113→        }
   114→        let request = UNNotificationRequest(identifier: ProcessInfo.processInfo.globallyUniqueString,
   115→                                            content: content,
   116→                                            trigger: nil)
   117→        do {
   118→            try await notificationCenter.add(request)
   119→            MXLog.info("Show local notification succeeded")
   120→        } catch {
   121→            MXLog.error("Show local notification failed: \(error)")
   122→        }
   123→    }
   124→    
   125→    func removeDeliveredMessageNotifications(for roomID: String) async {
   126→        let notificationsIdentifiers = await notificationCenter
   127→            .deliveredNotifications()
   128→            .filter { $0.request.content.roomID == roomID }
   129→            .map(\.request.identifier)
   130→        notificationCenter.removeDeliveredNotifications(withIdentifiers: notificationsIdentifiers)
   131→    }
   132→    
   133→    func removeDeliveredNotificationsForFullyReadRooms(_ rooms: [RoomSummary]) async {
   134→        let roomsToLastMessageDates = rooms
   135→            .filter { $0.hasUnreadMessages == false }
   136→            .reduce(into: [:]) { partialResult, roomSummary in
   137→                partialResult[roomSummary.id] = roomSummary.lastMessageDate
   138→            }
   139→        
   140→        let notificationsIdentifiers = await notificationCenter
   141→            .deliveredNotifications()
   142→            .filter { notification in
   143→                guard let roomID = notification.request.content.roomID,
   144→                      let lastMessageDate = roomsToLastMessageDates[roomID] else {
   145→                    return false
   146→                }
   147→                    
   148→                return notification.date <= lastMessageDate
   149→            }
   150→            .map(\.request.identifier)
   151→        
   152→        notificationCenter.removeDeliveredNotifications(withIdentifiers: notificationsIdentifiers)
   153→    }
   154→
   155→    private func setPusher(with deviceToken: Data, clientProxy: ClientProxyProtocol) async -> Bool {
   156→        do {
   157→            let defaultPayload = APNSPayload(aps: APSInfo(mutableContent: 1,
   158→                                                          alert: APSAlert(locKey: "Notification",
   159→                                                                          locArgs: [])),
   160→                                             pusherNotificationClientIdentifier: clientProxy.pusherNotificationClientIdentifier)
   161→
   162→            let configuration = try await PusherConfiguration(identifiers: .init(pushkey: deviceToken.base64EncodedString(),
   163→                                                                                 appId: appSettings.pusherAppID),
   164→                                                              kind: .http(data: .init(url: appSettings.pushGatewayNotifyEndpoint.absoluteString,
   165→                                                                                      format: .eventIdOnly,
   166→                                                                                      defaultPayload: defaultPayload.toJsonString())),
   167→                                                              appDisplayName: "\(InfoPlistReader.main.bundleDisplayName) (iOS)",
   168→                                                              deviceDisplayName: UIDevice.current.name,
   169→                                                              profileTag: pusherProfileTag(),
   170→                                                              lang: Bundle.app.preferredLocalizations.first ?? "en")
   171→            try await clientProxy.setPusher(with: configuration)
   172→            MXLog.info("Set pusher succeeded")
   173→            return true
